function renderPrivacyPage({ homeHref = "/" } = {}) {
  const homeLink = escapeHtml(homeHref);

  return `<!DOCTYPE html>
<html lang="es">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>ActivaBar | Privacidad</title>
    <link rel="icon" type="image/jpeg" href="${ACTIVABAR_PUBLIC_FAVICON_DATA_URI}" />
    <link rel="shortcut icon" href="${ACTIVABAR_PUBLIC_FAVICON_DATA_URI}" />
    <link rel="apple-touch-icon" href="${ACTIVABAR_PUBLIC_FAVICON_DATA_URI}" />
    <meta name="theme-color" content="#101716" />
    <style>
      :root {
        --bg: #faf9f5;
        --text: #1f241a;
        --muted: #5f6656;
        --line: rgba(62, 82, 25, 0.12);
        --olive: #3e5219;
      }
      * { box-sizing: border-box; }
      body {
        margin: 0;
        font-family: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        background: var(--bg);
        color: var(--text);
      }
      main {
        width: min(860px, calc(100vw - 32px));
        margin: 48px auto;
        padding: 32px;
        border-radius: 24px;
        background: rgba(255,255,255,0.76);
        border: 1px solid var(--line);
      }
      h1, h2 { color: var(--olive); }
      p, li { color: var(--muted); line-height: 1.75; }
      a { color: inherit; }
    </style>
  </head>
  <body>
    <main>
      <p><a href="${homeLink}">Volver a ActivaBar</a></p>
      <h1>Privacidad</h1>
      <p>
        ActivaBar es un servicio para bares y restaurantes orientado a la captacion
        y reactivacion de clientes mediante QR y WhatsApp.
      </p>
      <h2>Datos tratados</h2>
      <p>
        Podemos tratar telefono, origen del QR, consentimiento, actividad comercial
        y datos operativos necesarios para prestar el servicio al restaurante.
      </p>
      <h2>Finalidad</h2>
      <p>
        Gestionar altas, bajas, comunicaciones promocionales y medicion basica del
        rendimiento de las acciones comerciales del local.
      </p>
      <h2>Derechos</h2>
      <p>
        El usuario puede solicitar baja de comunicaciones y ejercer sus derechos de
        acceso, rectificacion o supresion a traves del canal habilitado por el
        restaurante responsable.
      </p>
      <h2>Contacto</h2>
      <p>
        Para consultas sobre privacidad o uso del servicio, utiliza el canal de
        contacto del negocio que te dio acceso a la promocion.
      </p>
    </main>
  </body>
</html>`;
}

function renderDemoRequestPage({
  formAction = "/demo",
  homeHref = "/",
  errorMessage = "",
  successMessage = "",
  values = {},
} = {}) {
  const action = escapeHtml(formAction);
  const homeLink = escapeHtml(homeHref);
  const errorBanner = errorMessage
    ? `<div class="banner error">${escapeHtml(errorMessage)}</div>`
    : "";
  const successBanner = successMessage
    ? `<div class="banner ok">${escapeHtml(successMessage)}</div>`
    : "";
  const field = (name) => escapeHtml(values[name] || "");

  return `<!DOCTYPE html>
<html lang="es">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>ActivaBar | Solicitar demo</title>
    <link rel="icon" type="image/jpeg" href="${ACTIVABAR_PUBLIC_FAVICON_DATA_URI}" />
    <link rel="shortcut icon" href="${ACTIVABAR_PUBLIC_FAVICON_DATA_URI}" />
    <link rel="apple-touch-icon" href="${ACTIVABAR_PUBLIC_FAVICON_DATA_URI}" />
    <meta name="theme-color" content="#101716" />
    <style>
      :root {
        --bg: #faf9f5;
        --panel: rgba(255,255,255,0.86);
        --text: #1f241a;
        --muted: #5f6656;
        --line: rgba(62, 82, 25, 0.12);
        --olive: #3e5219;
        --olive-2: #556b2f;
        --wine: #af2b3e;
      }
      * { box-sizing: border-box; }
      body {
        margin: 0;
        font-family: "Manrope", ui-sans-serif, system-ui, sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top, rgba(85, 107, 47, 0.14), transparent 28%),
          linear-gradient(180deg, #f7f4ec 0%, #faf9f5 100%);
      }
      .wrap {
        width: min(1100px, calc(100vw - 32px));
        margin: 40px auto 72px;
      }
      .topbar {
        display: flex;
        justify-content: space-between;
        align-items: center;
        gap: 16px;
        margin-bottom: 24px;
      }
      .brand {
        font-size: 1.5rem;
        font-weight: 800;
        color: var(--olive);
        text-decoration: none;
      }
      .back {
        color: var(--muted);
        text-decoration: none;
        font-weight: 700;
      }
      .panel {
        display: grid;
        grid-template-columns: minmax(0, 1.05fr) minmax(300px, 0.85fr);
        gap: 24px;
      }
      .card {
        background: var(--panel);
        border: 1px solid var(--line);
        border-radius: 28px;
        padding: 28px;
        box-shadow: 0 22px 54px rgba(25, 31, 18, 0.08);
      }
      h1, h2, p { margin-top: 0; }
      h1, h2 { color: var(--olive); }
      p { color: var(--muted); line-height: 1.7; }
      .banner {
        margin-bottom: 18px;
        border-radius: 16px;
        padding: 14px 16px;
        font-size: 14px;
      }
      .banner.error {
        color: #7b1826;
        background: rgba(175, 43, 62, 0.09);
        border: 1px solid rgba(175, 43, 62, 0.28);
      }
      .banner.ok {
        color: #1f4d17;
        background: rgba(85, 107, 47, 0.12);
        border: 1px solid rgba(85, 107, 47, 0.28);
      }
      form {
        display: grid;
        gap: 16px;
      }
      .grid-2 {
        display: grid;
        gap: 16px;
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }
      label {
        display: block;
        margin-bottom: 8px;
        color: var(--muted);
        font-size: 0.92rem;
        font-weight: 700;
      }
      input, textarea {
        width: 100%;
        border-radius: 16px;
        border: 1px solid var(--line);
        padding: 14px 16px;
        font: inherit;
        color: var(--text);
        background: rgba(255,255,255,0.86);
      }
      textarea {
        min-height: 140px;
        resize: vertical;
      }
      button {
        border: 0;
        border-radius: 999px;
        padding: 14px 22px;
        font: inherit;
        font-weight: 800;
        color: #fff;
        background: linear-gradient(15deg, var(--olive), var(--olive-2));
        cursor: pointer;
      }
      .small {
        font-size: 0.9rem;
      }
      .hidden-field {
        position: absolute;
        left: -9999px;
        opacity: 0;
        pointer-events: none;
      }
      ul {
        margin: 0;
        padding-left: 18px;
        color: var(--muted);
        line-height: 1.8;
      }
      @media (max-width: 900px) {
        .panel,
        .grid-2 {
          grid-template-columns: 1fr;
        }
      }
    </style>
  </head>
  <body>
    <div class="wrap">
      <div class="topbar">
        <a class="brand" href="${homeLink}"><img src="${ACTIVABAR_PUBLIC_LOGO_DATA_URI}" alt="ActivaBar" /></a>
        <a class="back" href="${homeLink}">Volver a la web</a>
      </div>
      <div class="panel">
        <section class="card">
          <p>Solicitar demo</p>
          <h1>Cuéntame qué local tienes y te escribo.</h1>
          <p>
            Déjame tus datos y el contexto de tu bar o restaurante. Así puedo
            enseñarte cómo encajaría ActivaBar en tu operativa real.
          </p>
          ${errorBanner}
          ${successBanner}
          <form method="post" action="${action}">
            <div class="grid-2">
              <div>
                <label for="name">Nombre</label>
                <input id="name" name="name" required value="${field("name")}" />
              </div>
              <div>
                <label for="businessName">Nombre del local</label>
                <input id="businessName" name="businessName" required value="${field("businessName")}" />
              </div>
            </div>
            <div class="grid-2">
              <div>
                <label for="email">Email</label>
                <input id="email" name="email" type="email" required value="${field("email")}" />
              </div>
              <div>
                <label for="phone">WhatsApp o teléfono</label>
                <input id="phone" name="phone" required value="${field("phone")}" />
              </div>
            </div>
            <div class="grid-2">
              <div>
                <label for="city">Ciudad</label>
                <input id="city" name="city" value="${field("city")}" />
              </div>
              <div>
                <label for="locationsCount">Número de locales</label>
                <input id="locationsCount" name="locationsCount" type="number" min="1" step="1" value="${field("locationsCount")}" />
              </div>
            </div>
            <div>
              <label for="message">Cuéntame tu caso</label>
              <textarea id="message" name="message" placeholder="Qué tipo de bar tienes, si ya usas WhatsApp, qué te gustaría medir o mejorar...">${field("message")}</textarea>
            </div>
            <div class="hidden-field" aria-hidden="true">
              <label for="companyWebsite">No rellenar</label>
              <input id="companyWebsite" name="companyWebsite" tabindex="-1" autocomplete="off" />
            </div>
            <button type="submit">Enviar solicitud</button>
          </form>
        </section>
        <aside class="card">
          <p>Qué reviso en la demo</p>
          <h2>Lo que vamos a aterrizar contigo</h2>
          <ul>
            <li>Cómo captar leads con QR dentro del local.</li>
            <li>Qué promociones encajan con tus horas flojas.</li>
            <li>Cómo medir altas, bajas, envíos y retorno.</li>
            <li>Qué WhatsApp Business y qué TPV usa tu bar.</li>
            <li>Cómo dejar el sistema operativo para tu equipo.</li>
          </ul>
          <p class="small" style="margin-top: 18px;">
            Este formulario no crea ningún restaurante ni da acceso al panel.
            Solo registra una solicitud comercial para que pueda contactarte.
          </p>
        </aside>
      </div>
    </div>
  </body>
</html>`;
}

module.exports = {
  renderMarketingLanding,
  renderDemoRequestPage,
  renderPrivacyPage,
};
